#!/bin/sh
# Local AI Cat: Locked Use unlock helper. The app runs these commands as root,
# one admin prompt, when you press Install or Reinstall. The two values the app
# fills in are shown here as examples: the helper inside the app, and the code
# hashes (cdhash) of the app and the helper it measured on your Mac.
# authdb.py and rule.plist are the two base64 lines below, decoded.
set -eu
umask 022
d=$(/usr/bin/mktemp -d)
chmod 700 "$d"
trap '/bin/rm -rf "$d"' EXIT
printf '%s' '' | /usr/bin/base64 -D > "$d/authdb.py"
printf '%s' '' | /usr/bin/base64 -D > "$d/rule.plist"
/usr/bin/ditto "/Applications/Local AI Cat.app/Contents/Resources/LockedUseAuthorizationPlugin.bundle" "$d/LockedUseAuthorizationPlugin.bundle"
/usr/bin/codesign --verify --strict "$d/LockedUseAuthorizationPlugin.bundle"
/usr/bin/codesign --verify --strict -R='anchor apple generic and certificate leaf[subject.OU] = "599WAZ6282" and certificate 1[field.1.2.840.113635.100.6.2.6] exists and certificate leaf[field.1.2.840.113635.100.6.1.13] exists' "$d/LockedUseAuthorizationPlugin.bundle"
/usr/bin/codesign -dvvv "$d/LockedUseAuthorizationPlugin.bundle" 2>&1 | /usr/bin/grep -qx 'CDHash=bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'
/usr/bin/plutil -extract CFBundleExecutable raw "$d/LockedUseAuthorizationPlugin.bundle/Contents/Info.plist" | /usr/bin/grep -qx 'LockedUseAuthorizationPlugin'
/bin/chmod -R go-w "$d/LockedUseAuthorizationPlugin.bundle"
/usr/sbin/chown -R root:wheel "$d/LockedUseAuthorizationPlugin.bundle"
/usr/bin/security authorizationdb read system.login.screensaver > "$d/before.plist"
/usr/bin/python3 "$d/authdb.py" uninstall pldev.Seek-Deep-Local-AI.locked-use.unlock < "$d/before.plist" > "$d/unwired.plist"
/usr/bin/security authorizationdb write system.login.screensaver < "$d/unwired.plist"
if [ -L "/Library/Application Support/LocalAICat" ]; then echo 'locked-use: refusing symlinked /Library/Application Support/LocalAICat' >&2; exit 4; fi
/bin/mkdir -p "/Library/Application Support/LocalAICat"
/usr/sbin/chown root:wheel "/Library/Application Support/LocalAICat"
/bin/chmod 755 "/Library/Application Support/LocalAICat"
/bin/chmod -N "/Library/Application Support/LocalAICat"
if [ -L "/Library/Application Support/LocalAICat/locked-use" ]; then echo 'locked-use: refusing symlinked /Library/Application Support/LocalAICat/locked-use' >&2; exit 4; fi
/bin/mkdir -p "/Library/Application Support/LocalAICat/locked-use"
/usr/sbin/chown root:wheel "/Library/Application Support/LocalAICat/locked-use"
/bin/chmod 755 "/Library/Application Support/LocalAICat/locked-use"
/bin/chmod -N "/Library/Application Support/LocalAICat/locked-use"
printf '%s\n' 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' > "$d/trusted-cdhashes"
/usr/bin/install -m 0644 -o root -g wheel "$d/trusted-cdhashes" "/Library/Application Support/LocalAICat/locked-use/trusted-cdhashes"
/bin/mkdir -p "/Library/Security/SecurityAgentPlugins"
/bin/rm -rf "/Library/Security/SecurityAgentPlugins/LockedUseAuthorizationPlugin.bundle.staging"
/usr/bin/ditto "$d/LockedUseAuthorizationPlugin.bundle" "/Library/Security/SecurityAgentPlugins/LockedUseAuthorizationPlugin.bundle.staging"
/bin/rm -rf "/Library/Security/SecurityAgentPlugins/LockedUseAuthorizationPlugin.bundle"
/bin/mv "/Library/Security/SecurityAgentPlugins/LockedUseAuthorizationPlugin.bundle.staging" "/Library/Security/SecurityAgentPlugins/LockedUseAuthorizationPlugin.bundle"
/usr/bin/security authorizationdb write pldev.Seek-Deep-Local-AI.locked-use.unlock < "$d/rule.plist"
/usr/bin/python3 "$d/authdb.py" install pldev.Seek-Deep-Local-AI.locked-use.unlock < "$d/unwired.plist" > "$d/after.plist"
/usr/bin/security authorizationdb write system.login.screensaver < "$d/after.plist"
if ! /usr/bin/security authorizationdb read system.login.screensaver | /usr/bin/python3 "$d/authdb.py" verify pldev.Seek-Deep-Local-AI.locked-use.unlock; then /usr/bin/security authorizationdb write system.login.screensaver < "$d/unwired.plist"; echo 'locked-use: verification failed; unwired right restored' >&2; exit 3; fi
